// AIRI organisational profile — EDIT to match AIRI's real positioning and rules.
const AIRI = {
  name: "AIRI Foundation",
  mission: "Advance AI literacy and responsible AI education across Canada as a nonprofit.",
  stands_for: "AIRI exists to make AI understandable and safe for everyday Canadians, prioritising underserved communities and public-interest education over commercialisation.",
  values: ["responsible and ethical AI","equitable access","community empowerment","education over commercialisation","transparency"],
  focus_areas: ["AI literacy","AI education","responsible AI","digital skills","community education"],
  // Red lines: reasons to decline ON PRINCIPLE even if the opportunity is eligible and topical.
  red_lines: [
    "funders whose core business conflicts with responsible-AI values (e.g. mass surveillance, exploitative data practices)",
    "funding that requires AIRI to endorse or promote a specific product or vendor",
    "opportunities that pull AIRI away from education toward purely commercial delivery",
    "conditions that compromise AIRI's independence or public-interest mission"
  ],
  // Deterministic administrative eligibility:
  country_eligible: ["Canada","CA"],
  org_types_eligible: ["nonprofit","charity","not-for-profit"],
  funding_min: 5000,
  funding_max: 250000,
  currency: "CAD",
  min_lead_days: 7
};

function slugHash(s){ let h=5381; for(let i=0;i<s.length;i++){h=((h<<5)+h)+s.charCodeAt(i); h=h>>>0;} return h.toString(36); }

const src = $json.body ? $json.body : $json;
const title=(src.title||"").trim(), funder=(src.funder||"").trim(), url=(src.url||"").trim();
const opportunity_id = url ? "url_"+slugHash(url) : "kv_"+slugHash((funder+"|"+title).toLowerCase());

return [{ json: {
  opportunity_id, title, funder, url,
  amount: src.amount ?? null, currency: src.currency || AIRI.currency,
  deadline: src.deadline || null, country: src.country || null,
  org_type: src.org_type || null, description: src.description || "",
  airi: AIRI
}}];

const incoming = $('Normalize + AIRI Profile').first().json;
const row = items && items.length ? items[0].json : null;
// A real DB row has a stage AND matches this opportunity_id AND does NOT carry the 'airi' profile object.
const isRealRow = !!(row && row.stage && row.opportunity_id === incoming.opportunity_id && !row.airi);
return [{ json: { ...incoming, stage: isRealRow ? row.stage : 'new', is_new: !isRealRow } }];

const o=$json, A=o.airi, reasons=[];
if (o.country && !A.country_eligible.map(c=>c.toLowerCase()).includes(String(o.country).toLowerCase()))
  reasons.push("Country not eligible: "+o.country);
if (o.org_type && !A.org_types_eligible.map(t=>t.toLowerCase()).includes(String(o.org_type).toLowerCase()))
  reasons.push("Org type not eligible: "+o.org_type);
if (o.amount!=null && (o.amount<A.funding_min || o.amount>A.funding_max))
  reasons.push("Amount "+o.amount+" outside range "+A.funding_min+"-"+A.funding_max);
if (o.deadline){ const d=(new Date(o.deadline)-new Date())/86400000;
  if (isNaN(d)) reasons.push("Unparseable deadline: "+o.deadline);
  else if (d<A.min_lead_days) reasons.push("Deadline too soon ("+Math.round(d)+" days lead)"); }

const A2 = o.airi || {};
let gate_rich = "";
if (reasons.length) {
  gate_rich =
    `GRANT OVERVIEW:\n${o.funder || "Unknown funder"} — ${o.title || ""}. ${o.description || ""}\n\n` +
    `AIRI ELIGIBILITY CONTEXT:\nAIRI accepts ${(A2.org_types_eligible||[]).join(", ")} organizations in ${(A2.country_eligible||[]).join(", ")}, for amounts ${A2.funding_min}-${A2.funding_max} ${A2.currency||"CAD"}, with at least ${A2.min_lead_days} days lead time.\n\n` +
    `WHY IT DOES NOT QUALIFY (administrative eligibility):\n${reasons.map((r,i)=>`${i+1}. ${r}`).join("\n")}\n\n` +
    `WHAT WOULD BE NEEDED:\nThe opportunity must satisfy AIRI's administrative eligibility above (eligible country, organization type, funding range, and deadline lead time) before it can be evaluated for mission fit.\n\n` +
    `NOTE:\nThis grant was declined at the administrative gate and was not assessed against AIRI's 30 focus areas.`;
}
return [{ json: { ...o, gate_pass: reasons.length===0, gate_reason: reasons.join("; ")||"Passed hard eligibility gate", gate_rich } }];

const raw = ($json.text ?? $json.output ?? "").toString();
const cleaned = raw.replace(/```json/gi, "").replace(/```/g, "").trim();
let ev;
try {
  ev = JSON.parse(cleaned);
} catch (e) {
  ev = {
    summary: "",
    primary_pillar: "None",
    matched_pillars: [],
    matched_focus_areas: [],
    eligibility: "Not eligible",
    qualifies: "do_not_qualify",
    approval_reasons: [],
    rejection_reasons: ["Model output could not be parsed as JSON"],
    watch_outs: ["Model output could not be parsed as JSON"],
    capacity_fit: "",
    effort_estimate: "unknown",
    recommendation: "Decline"
  };
}

const base = $('Hard Eligibility Gate').first().json;

const matched_pillars = Array.isArray(ev.matched_pillars) ? ev.matched_pillars : [];
const matched_focus_areas = Array.isArray(ev.matched_focus_areas) ? ev.matched_focus_areas : [];
const qualifies = (ev.qualifies || "do_not_qualify").toLowerCase();

// Build a human-readable reject reason string that is ALWAYS populated when not qualifying
let rejection_reasons = Array.isArray(ev.rejection_reasons) ? ev.rejection_reasons : [];
if (qualifies !== "qualify" && rejection_reasons.length === 0) {
  if (matched_pillars.length === 0) {
    rejection_reasons = ["Grant does not match any of AIRI's 6 pillars / 30 focus areas."];
  } else {
    rejection_reasons = ["Grant matched a pillar but did not meet eligibility requirements."];
  }
}



// Build a DETAILED, structured rejection reason with headers.
const rd = ev.rejection_detail || null;
const H = (label, val) => (val && String(val).trim()) ? `\n${label}:\n${String(val).trim()}\n` : "";
let rich_rejection = "";
if (qualifies !== "qualify") {
  if (rd) {
    rich_rejection =
      H("GRANT OVERVIEW", rd.grant_overview) +
      H("AIRI MISSION CONTEXT", rd.airi_mission_context) +
      H("WHY IT DOES NOT QUALIFY", rd.why_not_qualifying || rejection_reasons.join("; ")) +
      H("WHAT WOULD BE NEEDED", rd.missing_elements) +
      H("WHO THIS GRANT WOULD SUIT", rd.who_it_suits) +
      H("RECONSIDERATION NOTE", rd.reconsideration_note);
  }
  if (!rich_rejection.trim()) {
    rich_rejection =
      `GRANT OVERVIEW:\n${base.funder || "Unknown funder"} — ${base.title || ""}. ${ev.summary || ""}\n\n` +
      `WHY IT DOES NOT QUALIFY:\n${rejection_reasons.join("; ") || "Does not match AIRI's 6 pillars / 30 focus areas."}\n\n` +
      `WHO THIS GRANT WOULD SUIT:\nAn organization whose mission matches this grant's actual domain.`;
  }
  rich_rejection = rich_rejection.trim();
}


// Flag an explicit values / red-line / mission conflict (distinct from simply not matching a pillar)
const _rjoin = (Array.isArray(rejection_reasons)?rejection_reasons.join(" "):"").toLowerCase();
const values_conflict = (qualifies !== "qualify") && /(value|red.?line|mission|conflict|surveillance|endorse|independence|commercial)/.test(_rjoin);


// Pre-build email HTML so the email nodes only need one simple expression.
const _title = base.title || "";
const _funder = base.funder || "";
const _url = base.url || "";
const _esc = s => String(s==null?"":s);
const _ul = arr => (Array.isArray(arr)&&arr.length) ? "<ul>"+arr.map(x=>"<li>"+_esc(x)+"</li>").join("")+"</ul>" : "<p>None</p>";

const approval_email_html =
  "<h3>Funding opportunity — review before sign-off</h3>" +
  "<p><b>What this is:</b> "+_esc(ev.summary)+"</p>" +
  "<table cellpadding='6' style='border-collapse:collapse'>" +
  "<tr><td><b>Funder</b></td><td>"+_esc(_funder)+"</td></tr>" +
  "<tr><td><b>Amount</b></td><td>"+_esc(base.amount)+" "+_esc(base.currency)+"</td></tr>" +
  "<tr><td><b>Deadline</b></td><td>"+_esc(base.deadline)+"</td></tr>" +
  "<tr><td><b>Primary pillar</b></td><td>"+_esc(ev.primary_pillar||(matched_pillars[0]||"None"))+"</td></tr>" +
  "<tr><td><b>All matched pillars</b></td><td>"+_esc(matched_pillars.join("; "))+"</td></tr>" +
  "<tr><td><b>Eligibility</b></td><td>"+_esc(ev.eligibility)+"</td></tr>" +
  "<tr><td><b>Recommendation</b></td><td>"+_esc(ev.recommendation)+"</td></tr>" +
  "<tr><td><b>Effort</b></td><td>"+_esc(ev.effort_estimate)+"</td></tr>" +
  "</table>" +
  "<p><b>Matched focus areas:</b></p>"+_ul(matched_focus_areas) +
  "<p><b>Why it aligns with AIRI — reasons to approve:</b></p>"+_ul(ev.approval_reasons) +
  "<p><b>Capacity fit:</b> "+_esc(ev.capacity_fit)+"</p>" +
  "<p><b>Watch-outs:</b></p>"+_ul(ev.watch_outs) +
  "<p><a href='"+_esc(_url)+"'>View the full opportunity</a></p>" +
  "<p>Knowing the above, the decision is simply: <b>do we want to pursue this?</b></p>";

const reject_email_html =
  "<h3>Funding opportunity — not pursued</h3>" +
  "<p><b>Funder:</b> "+_esc(_funder)+"</p>" +
  "<p><b>Opportunity:</b> "+_esc(_title)+"</p>" +
  "<pre style='white-space:pre-wrap;font-family:inherit'>"+_esc(rich_rejection)+"</pre>" +
  "<p><a href='"+_esc(_url)+"'>View the source opportunity</a></p>";

return [{ json: {
  ...base,
  summary: ev.summary || "",
  primary_pillar: ev.primary_pillar || (matched_pillars[0] || "None"),
  matched_pillars,
  matched_focus_areas,
  eligibility: ev.eligibility || "Not eligible",
  qualifies,
  approval_reasons: Array.isArray(ev.approval_reasons) ? ev.approval_reasons : [],
  rejection_reasons,
  watch_outs: Array.isArray(ev.watch_outs) ? ev.watch_outs : [],
  capacity_fit: ev.capacity_fit || "",
  effort_estimate: ev.effort_estimate || "unknown",
  recommendation: ev.recommendation || "Decline",
  // convenience joined strings for downstream logging / docx
  matched_pillars_str: matched_pillars.join("; "),
  matched_focus_areas_str: matched_focus_areas.join("; "),
  approval_reasons_str: (Array.isArray(ev.approval_reasons) ? ev.approval_reasons : []).map((r,i)=>`${i+1}. ${r}`).join("\n"),
  rejection_reasons_str: rejection_reasons.map((r,i)=>`${i+1}. ${r}`).join("\n"),
  rejection_detail: rd,
  values_conflict: values_conflict,
  approval_email_html: approval_email_html,
  reject_email_html: reject_email_html,
  rich_rejection: rich_rejection,
  watch_outs_str: (Array.isArray(ev.watch_outs) ? ev.watch_outs : []).map((r,i)=>`${i+1}. ${r}`).join("\n")
}}];

// Build a professional Application Prep document (HTML that opens cleanly in Word) 
// from the parsed evaluation. Output as binary so it can be saved/emailed as a document.
const d = $('Parse Evaluation').first().json;

const esc = (s) => String(s ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
const list = (arr) => (Array.isArray(arr) && arr.length)
  ? "<ul>" + arr.map(x => `<li>${esc(x)}</li>`).join("") + "</ul>"
  : "<p class='muted'>None</p>";

const today = new Date().toISOString().slice(0,10);

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Application Prep — ${esc(d.title)}</title>
<style>
  body{font-family:Calibri,Arial,sans-serif;color:#222;max-width:800px;margin:40px auto;line-height:1.5;}
  h1{color:#1F5C8C;font-size:24px;margin-bottom:4px;}
  h2{color:#1F5C8C;font-size:16px;border-bottom:2px solid #1F5C8C;padding-bottom:4px;margin-top:26px;}
  .sub{color:#666;font-size:13px;margin-bottom:20px;}
  table{border-collapse:collapse;width:100%;margin:8px 0;}
  td{border:1px solid #ccc;padding:8px;font-size:14px;vertical-align:top;}
  td.k{background:#f2f6fa;font-weight:bold;width:170px;}
  ul{margin:6px 0 6px 0;padding-left:22px;} li{margin-bottom:4px;}
  .muted{color:#888;font-style:italic;}
  .badge{display:inline-block;background:#1F5C8C;color:#fff;padding:3px 10px;border-radius:4px;font-size:13px;}
  .foot{margin-top:30px;color:#888;font-size:12px;border-top:1px solid #ddd;padding-top:10px;}
</style></head>
<body>
  <h1>AIRI Foundation — Application Prep</h1>
  <div class="sub">Grant application preparation record &nbsp;•&nbsp; Generated ${today}</div>

  <h2>Opportunity</h2>
  <table>
    <tr><td class="k">Title</td><td>${esc(d.title)}</td></tr>
    <tr><td class="k">Funder</td><td>${esc(d.funder)}</td></tr>
    <tr><td class="k">Amount</td><td>${esc(d.amount)} ${esc(d.currency)}</td></tr>
    <tr><td class="k">Deadline</td><td>${esc(d.deadline)}</td></tr>
    <tr><td class="k">Country</td><td>${esc(d.country)}</td></tr>
    <tr><td class="k">URL</td><td>${esc(d.url)}</td></tr>
    <tr><td class="k">Summary</td><td>${esc(d.summary)}</td></tr>
  </table>

  <h2>Pillar Alignment</h2>
  <table>
    <tr><td class="k">Primary pillar</td><td><span class="badge">${esc(d.primary_pillar)}</span></td></tr>
    <tr><td class="k">All matched pillars</td><td>${esc(d.matched_pillars_str) || "<span class='muted'>None</span>"}</td></tr>
    <tr><td class="k">Matched focus areas</td><td>${list(d.matched_focus_areas)}</td></tr>
    <tr><td class="k">Eligibility</td><td>${esc(d.eligibility)}</td></tr>
    <tr><td class="k">Recommendation</td><td><b>${esc(d.recommendation)}</b></td></tr>
  </table>

  <h2>Why AIRI Should Pursue This</h2>
  ${list(d.approval_reasons)}

  <h2>Watch-Outs & Considerations</h2>
  ${list(d.watch_outs)}

  <h2>Capacity Fit</h2>
  <p>${esc(d.capacity_fit) || "<span class='muted'>Not specified</span>"}</p>
  <p><b>Effort estimate:</b> ${esc(d.effort_estimate)}</p>

  <h2>Application Prep Checklist</h2>
  <ul>
    <li>Assign an owner / lead for this application</li>
    <li>Proposal narrative aligned to the matched focus areas above</li>
    <li>Budget prepared (within ${esc(d.amount)} ${esc(d.currency)})</li>
    <li>Organization registration &amp; nonprofit documentation</li>
    <li>Letters of support from partners (university / community / municipal as relevant)</li>
    <li>Confirm submission format and deadline: ${esc(d.deadline)}</li>
  </ul>

  <div class="foot">AIRI Foundation • Applied AI &amp; Robotics Innovation • Automated evaluation record. Human review required before submission.</div>
</body></html>`;

const fileName = `Application_Prep_${(d.title||"opportunity").replace(/[^a-z0-9]+/gi,"_").slice(0,50)}.doc`;
const binary = await this.helpers.prepareBinaryData(Buffer.from(html, "utf-8"), fileName, "application/msword");

return [{ json: { ...d, prep_document_generated: true, prep_file_name: fileName }, binary: { data: binary } }];

// MOCK evaluation output for testing (replace path with real Gemini output in production).
// Matches the new pillar-based, score-free schema.
const text = JSON.stringify({
  summary: "Funds a Canadian nonprofit to deliver AI literacy and responsible-AI education to remote and Indigenous communities in northern Canada.",
  primary_pillar: "Civic & Cultural AI Literacy",
  matched_pillars: ["Civic & Cultural AI Literacy", "Applied R&D, Ethics & Governance"],
  matched_focus_areas: [
    "1. Community AI Literacy & Education",
    "2. Underrepresented & Diverse Demographics",
    "11. Responsible & Ethical AI Design"
  ],
  eligibility: "Eligible",
  qualifies: "qualify",
  approval_reasons: [
    "Directly advances Focus Area 1 (Community AI Literacy & Education) through education for remote communities",
    "Serves equity-deserving groups per Focus Area 2 (Underrepresented & Diverse Demographics), including Indigenous communities",
    "Responsible-AI education aligns with Focus Area 11 (Responsible & Ethical AI Design)"
  ],
  rejection_reasons: [],
  watch_outs: ["Confirm delivery capacity for remote/northern travel and scheduling"],
  capacity_fit: "Strong — matches AIRI's core AI-literacy programming and community reach",
  effort_estimate: "medium",
  recommendation: "Proceed"
});
return [{ json: { text } }];
